                                break
                            except ValueError:
                                continue
                        else:
                            days_to_exp = 30
                    else:
                        days_to_exp = 30
                except (ValueError, TypeError):
                    days_to_exp = 30

            # Ensure days_to_exp is always a positive integer
            days_to_exp = max(1, int(days_to_exp))
            days_to_expiry = days_to_exp
        except Exception as e:
