@app.route("/api/stripe/create-checkout", methods=["POST"])
@require_auth
def create_checkout_session():
    """Create Stripe checkout session for subscription"""
    from stripe_manager import StripeManager

    data = request.get_json()
    plan_tier_str = data.get('plan_tier')
    billing_interval = data.get('billing_interval', 'monthly')  # 'monthly' or 'weekly'
    currency = data.get('currency', 'usd')  # 'usd', 'eur', 'gbp', 'usdc'
    payment_type = data.get('payment_type', 'card')  # 'card' or 'crypto'

    if not plan_tier_str:
        return jsonify({
            'status': 'error',
            'message': 'Plan tier required'
        }), 400

    # Validate billing interval
    if billing_interval not in ['monthly', 'weekly']:
        return jsonify({
            'status': 'error',
            'message': f'Invalid billing interval: {billing_interval}. Must be "monthly" or "weekly"'
        }), 400

    # Validate payment type
    if payment_type not in ['card', 'crypto']:
        return jsonify({
            'status': 'error',
            'message': f'Invalid payment type: {payment_type}. Must be "card" or "crypto"'
        }), 400

    # Validate crypto payment requirements
    if payment_type == 'crypto' and currency != 'usdc':
        return jsonify({
            'status': 'error',
            'message': 'Crypto payments are only available with USDC currency'
        }), 400

    # Convert string to PlanTier enum
    try:
        plan_tier = PlanTier(plan_tier_str)
    except ValueError:
        return jsonify({
            'status': 'error',
            'message': f'Invalid plan tier: {plan_tier_str}'
        }), 400

    if plan_tier == PlanTier.FREE:
        return jsonify({
            'status': 'error',
            'message': 'Cannot checkout free tier'
        }), 400

    user = request.current_user

    # Check if user already has an active subscription
    from db_utils import DatabaseManager
    current_sub = DatabaseManager.get_active_subscription(user.id)
    if current_sub and current_sub.plan.tier != PlanTier.FREE:
        return jsonify({
            'status': 'error',
            'message': 'You already have an active subscription. Please manage it through the customer portal.'
        }), 400

    # Create checkout session
    base_url = request.host_url.rstrip('/')
    success_url = f"{base_url}/subscription/success?session_id={{CHECKOUT_SESSION_ID}}"
    cancel_url = f"{base_url}/subscription/cancel"

    session_data = StripeManager.create_checkout_session(
        user_id=user.id,
        plan_tier=plan_tier,
        billing_interval=billing_interval,
        success_url=success_url,
        cancel_url=cancel_url,
        currency=currency,
        payment_type=payment_type
    )

    if not session_data:
        return jsonify({
            'status': 'error',
            'message': 'Failed to create checkout session'
        }), 500

    return jsonify({
        'status': 'success',
        'message': 'Checkout session created',
        'session_id': session_data['session_id'],
        'checkout_url': session_data['url'],
        'billing_interval': session_data.get('billing_interval', billing_interval),
        'currency': session_data.get('currency', currency),
        'payment_type': session_data.get('payment_type', payment_type),
        'trial_days': session_data.get('trial_days')
    }), 200


